package app.flare.auto;
import android.content.*;import android.graphics.*;import android.net.*;import android.net.wifi.*;import android.view.View;
final class WifiStatus extends View {
 final Paint p=new Paint(3);final Path signal=new Path();final int primary,background,secondary;boolean on;ConnectivityManager cm;boolean registered;
 final ConnectivityManager.NetworkCallback callback=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network n){post(()->refresh());}@Override public void onLost(Network n){post(()->refresh());}@Override public void onCapabilitiesChanged(Network n,NetworkCapabilities cap){post(()->refresh());}};
 final BroadcastReceiver hotspot=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){refresh();}};
 WifiStatus(Context c){super(c);ThemeTokens t=ThemeTokens.get(c);primary=t.textPrimary;background=t.background;secondary=t.textSecondary;signal.moveTo(2,8);signal.cubicTo(7,3,17,3,22,8);signal.moveTo(5,11);signal.cubicTo(9,7,15,7,19,11);signal.moveTo(8,14);signal.cubicTo(10,12,14,12,16,14);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();cm=(ConnectivityManager)getContext().getSystemService(Context.CONNECTIVITY_SERVICE);try{cm.registerNetworkCallback(new NetworkRequest.Builder().addTransportType(NetworkCapabilities.TRANSPORT_WIFI).build(),callback);registered=true;}catch(RuntimeException ignored){}getContext().registerReceiver(hotspot,new IntentFilter("android.net.wifi.WIFI_AP_STATE_CHANGED"));refresh();}
 @Override protected void onDetachedFromWindow(){if(registered){cm.unregisterNetworkCallback(callback);registered=false;}getContext().unregisterReceiver(hotspot);super.onDetachedFromWindow();}
 void refresh(){boolean connected=false;try{for(Network n:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(n);if(cap!=null&&cap.hasTransport(NetworkCapabilities.TRANSPORT_WIFI))connected=true;}WifiManager wm=(WifiManager)getContext().getApplicationContext().getSystemService(Context.WIFI_SERVICE);connected|=((Integer)wm.getClass().getMethod("getWifiApState").invoke(wm))==13;}catch(Exception ignored){}setContentDescription(connected?"Wi-Fi connected or hotspot active":"Wi-Fi disconnected");if(on!=connected){on=connected;invalidate();}}
 protected void onDraw(Canvas c){super.onDraw(c);c.save();float size=Math.min(getWidth(),getHeight());c.translate((getWidth()-size)/2,(getHeight()-size)/2);c.scale(size/24,size/24);c.translate(2,2);c.scale(20f/24,20f/24);p.setColor(on?primary:secondary);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.8f);p.setStrokeCap(Paint.Cap.ROUND);c.drawPath(signal,p);p.setStyle(Paint.Style.FILL);c.drawCircle(12,17.5f,1.1f,p);if(!on){p.setStyle(Paint.Style.STROKE);p.setColor(background);p.setStrokeWidth(4);c.drawLine(16,16,22,22,p);c.drawLine(22,16,16,22,p);p.setColor(secondary);p.setStrokeWidth(1.6f);c.drawLine(16,16,22,22,p);c.drawLine(22,16,16,22,p);}c.restore();}
}
